"Верно. Григ написал музыку к одноимённой пьесе Ибсена.": "Тоғра. Григ Ибсенниң шу намдики пьесиси үчүн музика язған.",
"Неверно. Это пьеса Грига из сюиты «Пер Гюнт».": "Хата. Бу Григниң «Пер Гюнт» сюитисидики пьесиси.",
"Верно. Ударные очень распространены и нужны в ансамблях.": "Тоғра. Соқма қураллар интайин кәң тарқалған вә ансамбльларда зөрүр.",
"Неверно. Челеста относится к инструментам с определённой высотой звука.": "Хата. Челеста аваз егизлики мәлум қураллар қатариға киридиду.",
"Верно. Она автор и музыки, и слов этой песни.": "Тоғра. У бу нахшиниң музикисиниң һәм сөзиниң автори.",
