"Различать подгруппы струнных инструментов и называть произведения о воде и грозе.": "Тарлиқ қуралларниң кичик топлирини пәриқләндүрүп, су вә күркирәш һәққидики әсәрләрни аташ.",
"Струнные инструменты": "Тарлиқ қураллар",
"Это самая многочисленная группа инструментов. Их называют основой симфонического оркестра.": "Бу қуралларниң әң көп санлиқ топи. Уларни симфониялик оркестрниң асаси дәйду.",
"Народные струнные": "Хәлқ тарлиқ қураллири",
"Семейство народных струнных инструментов тоже очень разнообразно. Все струнные инструменты в мире условно делят на три подгруппы.": "Хәлқ тарлиқ қураллириниң аилиси һәм интайин хилму-хил. Дунядики барлиқ тарлиқ қуралларни шәртлик һалда үч кичик топқа бөлиду.",
"Щипковые": "Чекип чалидиған қураллар",
"Звук получают, защипывая струну пальцами или специальной пластинкой — плектром. Это домбра, гитара, арфа.": "Аваз тарни бармақ яки алаһидә пластинка — плектр билән чертиш арқилиқ чиқиду. Булар домбра, гитара, арфа.",
"Смычковые и ударные": "Яйлиқ вә соқма қураллар",
"У смычковых звук извлекают смычком из конского волоса: виолончель, кобыз. У ударных по струнам бьют палочками или молоточками: фортепиано, цимбалы.": "Яйлиқ қураллардики авазни ат қилидин ясалған яй билән чиқиридиду: виолончель, қобыз. Соқма қураллирида тарларға таяқча яки болға билән урушиду: фортепиано, цимбал.",
"Эолова арфа": "Эол арфиси",
"Её струны звучат от колебания воздуха, и музыкант ей не нужен. Это деревянный ящик с отверстием, внутри которого натянуты струны.": "Униң тарлири һаваниң тәврәнгинидин аваз чиқириду, униңға музыкант керәк әмәс. Бу тешиги бар яғач йәшик, униң ичигә тарлар тартилған.",
"Разложи струнные инструменты по подгруппам": "Тарлиқ қуралларни кичик топларға тәқсим қил",
"Определи, к какой подгруппе относится инструмент или способ звукоизвлечения.": "Қурал яки аваз чиқириш усулиниң қайси кичик топқа мансуплуғини ениқла.",
