"Называть группы духовых инструментов и объяснять, что такое сценические эффекты.": "Пүвләш қуралларниң топлирини атап, сәһнә эффектлириниң немә екәнлигини чүшәндүрүш.",
"Духовые инструменты": "Пүвләш қураллири",
"Это инструменты, которые звучат благодаря воздуху, который вдувает музыкант. Они делятся на три группы: медные, деревянные и клавишные.": "Бу музыкант пүвләйдиған һава арқилиқ аваз чиқиридиған қураллар. Улар үч топқа бөлиниду: мис, яғач вә клавишлиқ.",
"Медные и деревянные": "Мис вә яғач қураллар",
"К медным относятся труба, валторна, туба, горн, фанфары. К деревянным — дудка, флейта, саксофон, кларнет, фагот, балабан и зурна.": "Мис қураллириға труба, валторна, туба, горн, фанфар киридиду. Яғач қураллириға — дудка, флейта, саксофон, кларнет, фагот, балабан вә зурна киридиду.",
"Клавишные духовые": "Клавишлиқ пүвләш қураллири",
"К клавишным духовым относятся фисгармония, аккордеон, мелодика, баян и орган.": "Клавишлиқ пүвләш қураллириға фисгармония, аккордеон, мелодика, баян вә орган киридиду.",
"Сценические эффекты": "Сәһнә эффектлири",
"Так называют звуковое и световое сопровождение, иллюзии движения и превращения в спектакле, концерте или шоу. Слово пришло из латыни и означает «исполнение».": "Спектакль, консерт яки шоуда аваз вә яруқлуқ ярдими, һәрикәт вә өзгириш иллюзиялирини шундақ атайду. Бу сөз латин тилидин кәлгән вә «орунлаш» дегән мәнини билдүриду.",
"Рихард Вагнер": "Рихард Вагнер",
"Немецкий композитор и дирижёр (1813–1883). Его музыка «Полёт валькирий» рисует приближение крылатых коней. Помогают в этом динамические оттенки.": "Германиялик композитор вә дирижёр (1813–1883). Униң «Валкирияләрниң учуши» музикиси қанатлиқ атларниң йеқинлишишини сүрәтләйду. Буниңда динамикилиқ нәзәр түсләр ярдәм бериду.",
"Разложи духовые инструменты по группам": "Пүвләш қуралларни топларға тәқсим қил",
"Определи, к какой группе духовых относится каждый инструмент.": "Һәр бир қуралниң пүвләш қуралларидин қайси топқа мансуплуғини ениқла.",
"К какой группе относится инструмент?": "Қурал қайси топқа тәвә?",
