"Различать, как музыка передаёт дикий и укрощённый огонь, и называть произведения С. Прокофьева и П.И. Чайковского.": "Музикиниң явайи вә боюсундурулған утни қандақ ипадиләйдиғанлиғини пәриқләндүрүп, С. Прокофьев вә П.И. Чайковскийниң әсәрлирини аташ.",
"Огненный смерч": "Утлуқ қуюн",
"Это очень яркое, но очень опасное природное явление. Чаще всего оно возникает в горящем лесу, а ветер там сильнее 160 километров в час.": "Бу интайин ярқин, лекин интайин хәтәрлик тәбиәт һадисиси. У көпинчә көйүватқан ормандә пәйда болиду, у йәрдики шамал саатигә 160 километрдин күчлүк болиду.",
"Прокофьев и «Каменный цветок»": "Прокофьев вә «Тош гүл»",
"Композитор С. Прокофьев в балете «Каменный цветок» изобразил музыкой похожее явление. Танец Огневушки-поскакушки передаёт неуправляемый характер огненного вихря.": "Композитор С. Прокофьев «Тош гүл» балетида музика арқилиқ охшаш һадисини сүрәтлигән. Огневушка-поскакушкиниң уссули утлуқ қуюнниң башқурғили болмайдиған характерини ипадиләйду.",
"Укрощённый огонь": "Боюсундурулған ут",
"Человек научился управлять огнём: он обогревает и освещает жильё. Такой огонь спокойный и доброжелательный.": "Адәм утни башқурушни үгәнди: ут өйни иситиду вә яритиду. Бундақ ут таза вә меһрибан.",
"Чайковский и «У камелька»": "Чайковский вә «Оҗақ йенида»",
"Пьеса «У камелька» входит в цикл «Времена года» П.И. Чайковского. В ней музыка передаёт спокойный, добрый огонь и чувство тепла.": "«Оҗақ йенида» пьесиси П.И. Чайковскийниң «Йил пәсиллири» циклиға киридиду. Униңда музика тинч, меһрибан утни вә иссиқлиқ һессиятини ипадиләйду.",
"Огонь и безопасность": "Ут вә хәвпсизлик",
"Огонь может стать причиной пожара, поэтому очень важно соблюдать правила пожарной безопасности. Спички — не игрушка, а огонь — не забава!": "Ут янғинниң сәвәви болуши мумкин, шуңа янғин хәвпсизлики қаидилиригә әмәл қилиш интайин муһим. Гүгүрт — оюнчуқ әмәс, ут — оюн-тамаша әмәс!",
"Какой огонь в музыке?": "Музикида қандақ ут?",
"Определи, к какому огню относится каждая карточка.": "Һәр бир карточка қайси утқа мансуплуғини ениқла.",
