"Неверно. Человек научился управлять огнём: он обогревает и освещает жильё.": "Хата. Адәм утни башқурушни үгәнди: ут өйни иситиду вә яритиду.",
"Верно. Поэтому важно соблюдать правила пожарной безопасности.": "Тоғра. Шуңа янғин хәвпсизлики қаидилиригә әмәл қилиш муһим.",
"Неверно. Спички — не игрушка, огонь — не забава.": "Хата. Гүгүрт — оюнчуқ әмәс, ут — оюн-тамаша әмәс.",
"Найди: Огненный вихрь (Прокофьев)": "Тап: Утлуқ қуюн (Прокофьев)",
"Найди: Огонь у камелька (Чайковский)": "Тап: Оҗақ йениндики ут (Чайковский)",
"Найди: Огонь-помощник": "Тап: Ярдәмчи ут",
"Найди: Огонь-опасность": "Тап: Хәвплик ут",
"Урок 21. Фантазии природы": "21-дәрис. Тәбиәтниң хияллири",
"Фантазии природы": "Тәбиәтниң хияллири",
"Объяснять, что такое программная музыка, и называть примеры музыки, изображающей природу.": "Программилиқ музика дегән немә екәнлигини чүшәндүрүш вә тәбиәтни тәсвирләйдиған музикиға мисаллар келтүрүш.",
"Музыкальная живопись": "Музикилиқ рәсимчилик",
"Люди всегда делились впечатлениями от увиденного и услышанного. Есть даже выражение «музыкальная живопись» — музыка, которая рисует картины природы.": "Адәмләр һемишә көргән вә аңлиған тәсирати билән бөлүшкән. «Музикилиқ рәсимчилик» дегән ибариму бар — бу тәбиәт мәнзирилирини сизидиған музика.",
"Цикл П. Чайковского «Времена года» состоит из 12 пьес. Каждая пьеса — образ одного месяца года, чаще всего через пейзаж.": "П. Чайковскийниң «Йил пәсиллири» цикли 12 пьесидин тузулиду. Һәр бир пьеса — йилниң бир ейиниң образи, көпинчә мәнзирә арқилиқ.",
"Настроение сезона": "Пәсилниң кәйпияти",
"В небольших пьесах-акварелях отражено настроение сезона: зимние грёзы, весенняя свежесть, летнее раздолье, осенняя грусть.": "Кичик пьеса-акварельләрдә пәсилниң кәйпияти ипадиләнгән: қишлиқ хияллар, баһарниң тазилиғи, жазниң кәң-кушадилиғи, күзниң ғәмгинлиги.",
"Программная музыка": "Программилиқ музика",
"Это академическая музыка без слов, то есть инструментальная. Но к ней есть словесное указание на содержание: название или пояснение.": "Бу — сөзи йоқ академиялик музика, йәни чалғу музикиси. Лекин униңға мәзмунини көрситидиған сөз бар: нам яки чүшәндүрүш.",
"Заголовок и эпиграф": "Сәрләвһә вә эпиграф",
"Перед каждой из 12 миниатюр Чайковского есть заголовок и эпиграф — строчки из стихов русских поэтов. Они раскрывают характер музыки. Один из таких эпиграфов взят у А. Майкова.": "Чайковскийниң һәр бир 12 миниатюрисиниң алдида сәрләвһә вә эпиграф бар — рус шаирлириниң шеирлиридин елинған саплар. Улар музикиниң характерини ечип бериду. Шундақ эпиграфларниң бири А. Майковтин елинған.",
"Кто или что это?": "Ким яки немә?",
"Разложи карточки: произведение, термин или автор.": "Карточкиларни топларға бөл: әсәр, термин яки автор.",
"К какой группе относится?": "Қайси топқа мәнсуп?",
