"Верно. Композиторы обращались к самым разным картинам природы.": "Тоғра. Композиторлар тәбиәтниң интайин һәр хил картинилириға мураҗиәт қилған.",
"Неверно. Ещё к временам суток, дождю, снегу, лесу, морю, лугам и полям, земле и небу.": "Хата. Йәнә күн вақитлириға, ямғурға, қарға, ормангә, деңизға, чөл вә етизлиқларға, жутқа вә асманға.",
"Верно. Сочиняют сразу, без подготовки.": "Тоғра. Улар тәйярлиқсиз, шу заматла ижад қилиду.",
"Найди: Произведение": "Тап: Әсәр",
"Найди: Термин": "Тап: Термин",
"Найди: Автор": "Тап: Автор",
"Найди: Признак": "Тап: Бәлгү",
"Найди: Не признак": "Тап: Бәлгү әмәс",
"Урок 22. Музыка-призыв": "22-дәрис. Чақириқ музикиси",
"Музыка-призыв": "Чақириқ музикиси",
"Объяснять, как музыка призывает беречь природу, и называть песни и их авторов.": "Музиканиң тәбиәтни асришқа қандақ чақиридиғанлиғини чүшәндүрүш, нахшиларни вә уларниң авторлирини аташ.",
"Что такое призыв": "Чақириқ дегән немә",
"Призыв — это обращение, которое зовёт к действию. По-казахски это «шакыру», по-английски — «call».": "Чақириқ — ишқа чақиридиған мураҗиәт. Қазақчә бу «шакыру», инглизчә — «call».",
"Музыка, которая зовёт": "Чақиридиған музика",
"Многие музыкальные произведения не просто украшают нашу жизнь. Они становятся руководством к действию и помогают человеку сделать правильный выбор.": "Нурғун музикилиқ әсәрләр турмушимизни пәқәт безәпла қалмайду. Улар һәрикәткә йол көрситиду вә адәмгә тоғра таллаш қилишқа ярдәм бериду.",
"Экологическая тема": "Экологиялик тема",
"В музыке бывает экологическая тема — это охрана окружающей среды. Песни напоминают нам, что природу нужно беречь.": "Музикида экологиялик тема болиду — бу әтрап муһитни қоғдаш. Нахшилар бизгә тәбиәтни асраш керәклигини әсләтиду.",
"«Песня о земной красоте»": "«Жутниң гөзәллиги һәққидики нахша»",
"Эту песню написал Я. Дубравин. Она о красоте природы и о доброте, которой нужно делиться.": "Бу нахшини Я. Дубравин язған. У тәбиәтниң гөзәллиги вә бөлүшүш керәк болған меһриванлиқ һәққидә.",
"«Не дразните собак»": "«Итларни дәссимәң»",
"Эта песня из кинофильма «Происшествие». Музыку написал Е. Птичкин, слова — М. Пляцковский. Песня призывает добро относиться к животным и красоте земли.": "Бу нахша «Вақиә» кинофильмидин. Музикисини Е. Птичкин, сөзини М. Пляцковский язған. Нахша һайванларға меһриванлиқ билән муамилә қилишқа вә жутниң гөзәллигини асришқа чақириду.",
"Береги природу": "Тәбиәтни асраң",
"Барсик спрашивает: что помогает природе и животным, а что им вредит? Разложи карточки.": "Барсик сорайду: тәбиәт вә һайванларға немә ярдәм бериду, немә зиян келтүриду? Карточкиларни топларға бөл.",
"Так поступает друг природы": "Тәбиәтниң дости шундақ қилиду",
"Так поступать нельзя": "Шундақ қилишқа болмайду",
"Посадить дерево": "Дәрәқ тикиш",
"Пословица говорит: кто не сажал дерева, тому не лежать в тени.": "Мақалда ейтилиду: дәрәқ тикмигән адәм сайидә ятмайду.",
"Беречь молодую поросль": "Яш көчәтләрни асраш",
"Из неё вырастут большие деревья.": "Улардин чоң дәрәқләр өсиду.",
"Насыпать птицам зерно и крошки": "Қушларға дән вә ушшақ нан селиш",
"Так мы заботимся о птицах.": "Шундақ қилип биз қушларни қоғдаймиз.",
"Любоваться красотой земли и беречь её": "Жутниң гөзәллигигә қизиқип, уни асраш",
"Это призыв песни о земной красоте.": "Бу — жутниң гөзәллиги һәққидики нахшиниң чақириғи.",
"Дразнить собак": "Итларни дәссәш",
"Песня призывает так не делать.": "Нахша шундақ қилмаслиққа чақириду.",
"Гонять кошек": "Мушуқларни қоваш",
"Животных нельзя обижать.": "Һайванларни ренҗитишкә болмайду.",
"Пугать жуков": "Қоңғузларни қорқутуш",
"Жуки никого не трогают сами.": "Қоңғузлар һеч кимгә өзлири тәгмәйду.",
"Обижать бабочку на ветке": "Шахтики көпәләкни ренҗитиш",
"Бабочка никому не мешает.": "Көпәләк һеч кимгә тосалғу болмайду.",
"Две песни урока": "Дәрисниң икки нахшиси",
