"«Шакыру» значит «призыв».": "«Шакыру» — «чақириқ» дегән мәна.",
"Верно. Так объясняется слово «призыв».": "Тоғра. «Чақириқ» сөзи шундақ чүшәндүрүлиду.",
"Неверно. Многие произведения становятся руководством к действию.": "Хата. Нурғун әсәрләр һәрикәткә йол көрситиду.",
"Верно. Песни напоминают беречь природу.": "Тоғра. Нахшилар тәбиәтни асрашни әсләтиду.",
"Верно. Автор песни — Я. Дубравин.": "Тоғра. Нахшиниң автори — Я. Дубравин.",
"Неверно. Музыку написал Е. Птичкин.": "Хата. Музикисини Е. Птичкин язған.",
"Верно. М. Пляцковский — автор слов.": "Тоғра. М. Пляцковский — сөзниң автори.",
"Верно. Это верно.": "Тоғра. Бу тоғра.",
"Неверно. Она призывает добро относиться к животным.": "Хата. У һайванларға меһриванлиқ билән муамилә қилишқа чақириду.",
"Верно. Они о том, что деревья нужно сажать и беречь.": "Тоғра. Улар дәрәқләрни тикиш вә асраш керәкликини ейтиду.",
"Неверно. «Шакыру» значит «призыв».": "Хата. «Шакыру» — «чақириқ» дегән мәна.",
"Найди: Так поступает друг природы": "Тап: Тәбиәтниң дости шундақ қилиду",
"Найди: Так поступать нельзя": "Тап: Шундақ қилишқа болмайду",
"Найди: Песня о земной красоте": "Тап: Жутниң гөзәллиги һәққидики нахша",
"Найди: Не дразните собак": "Тап: Итларни дәссимәң",
"Урок 23. Мой любимец": "23-дәрис. Мениң сөйүмлүгүм",
"Мой любимец": "Мениң сөйүмлүгүм",
"Объяснять, что такое нотное переложение, и называть музыкальные произведения о любимых животных.": "Нота көчүрмисиниң (переложение) немә екәнлигини чүшәндүрүш вә сөйүмлүк һайванлар һәққидики музикилиқ әсәрләрни аташ.",
"Конь в музыке": "Музикидики ат",
"У казахского народа самым любимым и почитаемым животным всегда был конь, скакун. Многие композиторы рисовали музыкой его стремительные, неудержимые скачки.": "Қазақ хәлқи үчүн һемишә әң сөйүмлүк вә һөрмәтлик һайван — ат, чапқур болған. Нурғун композиторлар униң җүрәтлик, тосқунлуқсиз чапқанлиғини музика билән сизған.",
"Курмангазы и «Адай»": "Қурманғазы вә «Адай»",
"Великий казахский композитор Курмангазы создал музыкальную картину «Адай». В ней не просто скачки: он показал мужественный, героический дух древнего казахского рода Адай.": "Чоң қазақ композитори Қурманғазы «Адай» музикилиқ картинисини яратқан. Униңда пәқәт чапқанла әмәс: у қедимий қазақ уруғи Адайниң мәрт, баһадирлиқ роһини көрсәткән.",
"Одно произведение — разное исполнение": "Бир әсәр — һәр хил орунлаш",
"Кюй «Адай» можно услышать в трёх исполнениях: на домбре, в оркестре и с электронными инструментами. Произведение одно, а исполнение разное.": "«Адай» күйини үч хил орунлашта аңлашқа болиду: домбирида, оркестрда вә электрон қураллар билән. Әсәр бир, орунлаш һәр хил.",
"Что такое переложение": "Көчүрмә (переложение) дегән немә",
"Переложение — это музыкальное произведение, изложенное в иной форме. Барсик говорит: мелодия та же, а звучит по-новому!": "Көчүрмә (переложение) — башқа шәкилдә баян қилинған музикилиқ әсәр. Барсик дәйду: сайрами охшаш, лекин йеңичә аңлиниду!",
"Песни о любимцах и о мире": "Сөйүмлүк һайванлар вә дуня һәққидики нахшилар",
"У всех народов мира есть песни о домашних любимцах, например английская народная песня «Котятки и перчатки». А песня Л. Квинт «Здравствуй, мир» — о жеребёнке и о мире вокруг. Слово «мир» по-казахски — әлем.": "Дуняниң барлиқ хәлқлиридә өй һайванлири һәққидә нахшилар бар, мәсилән, инглиз хәлқ нахшиси «Мушукчақлар вә қолғаплар». «Салам, дуня» нахшиси болса — Л. Квинтниң — тайчақ вә әтрапимиздики дуня һәққидә. «Дуня» сөзи қазақчә — әлем.",
"Чья это песня или кюй?": "Бу кимниң нахшиси яки күйи?",
"Помоги Барсику разложить факты по произведениям.": "Барсикқа пакитларни әсәрләр бойичә топларға бөлүшкә ярдәм бериң.",
"К какому произведению относится этот факт?": "Бу пакит қайси әсәргә мәнсуп?",
