"Концерт": "Концерт",
"Концерт — это выступление музыкантов перед слушателями. По-казахски так же: концерт, по-английски — concert.": "Концерт — музыкантларниң аңлиғучилар алдида чиқиши. Қазақчиму шундақ: концерт, инглизчә — concert.",
"Концертная программа": "Концерт программиси",
