"Романс": "Романс",
"Романс — небольшое музыкальное сочинение для голоса в сопровождении инструмента, чаще фортепиано. Он написан на стихи лирического содержания.": "Романс — қурал (көпинчә фортепиано) һәмраһлиғида авазда орунлайдиған кичик музикилиқ әсәр. У лирикилиқ мәзмундики шеирларға язилиду.",
"Сергей Рахманинов": "Сергей Рахманинов",
