"Объяснять, как кюи Курмангазы и народные песни отражают любовь к Родине, и называть, что нужно беречь.": "Қурманғазиниң күйлири вә хәлқ нахшилириниң Вәтәнгә болған муһәббәтни қандақ ипадиләйдиғанлиғини чүшәндүрүш вә немини асраш керәкликини атап бериш.",
"Родина": "Вәтән",
"Родина по-казахски — Отан, по-английски — Homeland. Это страна, где мы живём и которую любим.": "Вәтән қазақчә — Отан, инглизчә — Homeland. Бу биз яшайдиған вә сөйидиған әл.",
"Любовь к Родине": "Вәтәнгә муһәббәт",
"В народе говорят, что любовь к Родине начинается у семейного очага, то есть в семье и дома.": "Хәлқ арисида Вәтәнгә муһәббәт аилә очиғидин, йәни аилидин вә өйдин башлиниду дейилиду.",
"Красота родного края": "Туғулған йурт гөзәллиги",
"В песнях, кюях, сказаниях и сказках авторы воспевали красоту родного края и призывали сохранять и оберегать её.": "Нахшилар, күйләр, дастанлар вә чөчәкләрдә авторлар туғулған йурт гөзәллигини мәдһийилигән вә уни сақлап асрашқа чақирған.",
"Кюй «Алатау»": "«Алатау» күйи",
"Композитор Курмангазы Сагырбайулы изобразил в кюе величественные горные вершины и красивую природу Заилийского Алатау. Кюй можно услышать в исполнении на домбре и в оркестровом варианте.": "Композитор Қурманғазы Сағырбайули күйдә Зайли Алатавниң улуқвар тағ чоққилирини вә гөзәл тәбиитини сүрәтлигән. Бу күйни домбирида орунлиғанда вә оркестр варианти билән аңлашқа болиду.",
"Что мы бережём": "Биз немини асраймиз",
"Люди стараются сохранить не только природные богатства, но и культурное наследие своего народа. Песня «Наурыз жыры» (музыка М. Жаманкуловой) — о празднике Наурыз.": "Адәмләр пәқәт тәбиий байлиқларни әмәс, өз хәлқиниң мәдәнийәт мирасини һәм сақлашқа тиришиду. «Наурыз жыры» нахшиси (музикиси М. Жаманқуловаға тәвә) — Нәврүз байрими һәққидә.",
"Разложи по произведениям": "Әсәрләр бойичә бөл",
"Барсик просит разобраться, что относится к кюю, а что к песне.": "Барсик күй билән нахшиға немиләрниң тәәллуқ екәнлигини айрип беришни тәләп қилиду.",
"К какому произведению относится?": "Қайси әсәргә мунасивәтлик?",
