"Музыкадағы таң көріністерін сипаттап, М. Мусоргскийдің, Э. Григтің және С. Еркімбековтің шығармаларын ажырата білу.": "Музикидики таң көрүнүшлирини тәсвирләп, М. Мусоргскийниң, Э. Григниң вә С. Еркімбековниң әсәрлирини пәриқләндүрәлишни билиш.",
"Композиторға не әсер етеді?": "Композиторға немә тәсир қилиду?",
"Композиторлар шабыттан, қиялдан, туған жеріне, халқына және табиғатына деген сүйіспеншіліктен шығарма жазады. Біз сүйіспеншілігімізді сөзбен айтсақ, олар музыкамен баяндайды.": "Композиторлар илһамдин, хиялдин, туғулған йәргә, хәлқигә вә табиитигә болған муһәббәттин әсәр йезиду. Биз муһәббитимизни сөз билән ейтсақ, улар музика билән баян қилиду.",
"Модест Петрович Мусоргский (1839–1881) — орыстың ұлы композиторы. Ол «Хованщина» операсына жазған «Мәскеу өзеніндегі таң» кіріспесімен танымал: онда арайлап атқан таң бейнеленеді.": "Модест Петрович Мусоргский (1839–1881) — русларниң бөйүк композитори. У «Хованщина» операсиға йезилған «Москва дәриясидики таң» кириш қисми билән тонулған: униңда йорутуп атқан таң тәсвирлиниду.",
"Эдвард Григ (1843–1907) — Норвегияның әйгілі композиторы, пианист, дирижёр. Ол «Пер Гюнт» сюитасының «Таң» шығармасында туған жерінің табиғатын, таң шапағын көркемдеуіш құралдар арқылы суреттеген.": "Эдвард Григ (1843–1907) — Норвегияниң даңлиқ композитори, пианист, дирижёр. У «Пер Гюнт» сюитисиниң «Таң» әсиридә туғулған йериниң табиитини ипадә васитилири арқилиқ сүритлигән.",
"С. Еркімбеков": "С. Еркімбеков",
"Серік Еркімбеков — белгілі композитор, ҚР еңбек сіңірген қайраткері. Оның «Отан таңы» шығармасы туған жердің сұлулығын көрсетеді.": "Серік Еркімбеков — тонулған композитор, ҚР әмгәк синдүргән паалийәтчиси. Униң «Отан таңы» әсири туғулған йәрниң гөзәллигини көрситиду.",
"Жаңа сөздер": "Йеңи сөзләр",
"Опера — вокалдық және аспаптық музыканы, театр өнерін біріктіретін жанр. Сюита — бір идеяға бағындырылған әртүрлі пьесалардан құралған шығарма. Интерпретация — орындаушының шығарманы көркем түсіндіруі.": "Опера — вокал вә әсвапий музикини, театр санитини бирләштүридиған жанр. Сюита — бир ғайигә бойсундурулған һәр хил пьесилардин тәркип тапқан әсәр. Интерпретация — орунлиғучиниң әсәрни бәдиий чүшәндүрүши.",
