"Бұл — А.Н. Скрябиннің симфониялық поэмасы. Оның екінші аты — «Поэма огня», яғни «От туралы поэма». Ол 1910 жылы жазылған.": "Бу — А.Н. Скрябинниң симфониялик поэмиси. Униң иккинчи нами — «Поэма огня», йәни «От һәққидики поэма». У 1910-жили йезилған.",
"Прометей туралы аңыз": "Прометей һәққидики әпсанә",
"Поэма ежелгі грек аңызына негізделген. Прометей Олимптен отты рұқсатсыз алып кетіп, адамдарға сыйлаған. Сол үшін құдайлар оны жартасқа мәңгі байлап қойған.": "Поэма қедимки грек әпсанисигә асасланған. Прометей Олимптин отни рухсәтсиз елип кетип, инсанларға соға қилған. Шуниң үчүн илаһлар уни қаяға мәңгү бағлап қойған.",
"Жарық партиясы": "Йоруқлуқ партияси",
"Скрябин оркестрге хор мен «жарық партиясын» қосқан. Композитордың ойынша, музыкамен бірге түрлі түсті прожектор сәулелері ауысып тұруы керек.": "Скрябин оркестрға хор билән «йоруқлуқ партиясини» қошқан. Композиторниң пикричә, музика билән биллә хилму-хил рәңлик прожектор нурлири алмишип туруши керәк.",
"Симфониялық поэма": "Симфониялик поэма",
"Симфониялық поэма — бір бөлімді симфониялық музыка жанры. Бұл — оркестрге арналған бағдарламалық шығарма.": "Симфониялик поэма — бир бөлүмлүк симфониялик музика жанри. Бу — оркестр үчүн программилиқ әсәр.",
