"Музыка арқылы су мен желдің бейнесін елестетіп, шығармаларды суреттермен және билермен салыстыра білу.": "Музика арқилиқ су билән шамалниң образини тәсәввур қилип, әсәрләрни рәсимләр вә уссуллар билән селиштуралишни билиш.",
