"Бұл шығарманың музыкасын С. Еркімбеков жазған. Тыңдағанда көз алдыңа судың көріністері елестейді.": "Бу әсәрниң музикисини С. Еркімбеков йезип чиққан. Аңлиғанда көз алдиңизға суниң көрүнүшлири кәлгәндәк болиду.",
