"Бұл шығарманың да музыкасын С. Еркімбеков жазған. Композитор музыка арқылы желдің уілін бейнелеген.": "Бу әсәрниң музикисини-му С. Еркімбеков йезип чиққан. Композитор музика арқилиқ шамалниң улишини сүритлигән.",
