"Жыл мезгілдеріне арналған А. Вивальди концерттерін және оркестр туралы негізгі ұғымдарды (оркестр, дирижёр, партитура, концерт) атай білу.": "Жил пәсиллиригә беғишланған А. Вивальди концертлирини вә оркестр һәққидики асасий чүшәнчиләрни (оркестр, дирижёр, партитура, концерт) атиялишни билиш.",
"Жылдың төрт мезгілі": "Жилниң төт пәсили",
"Қыс, көктем, жаз, күз бірінен кейін бірі ауысып отырады. Әр мезгілдің өз әсемдігі бар, сондықтан оған арнап өлеңдер, әндер мен музыкалық шығармалар жазылған.": "Қиш, баһар, яз, күз бири-бири билән алмишип туриду. Һәр пәсилниң өз гөзәллиги бар, шуңа уни мәдһийиләп шеирлар, нахшилар вә музикилиқ әсәрләр йезилған.",
"Вивальди (1678–1741) – итальян композиторы, асқан шебер скрипкашы, дирижёр. Ол Венеция қаласында дүниеге келген.": "Вивальди (1678–1741) — итальян композитори, интайин чебәс скрипкичи, дирижёр. У Венеция шәһиридә туғулған.",
"«Жыл мезгілдері» концерттері": "«Жил пәсиллири» концертлири",
"Вивальдидің ең танымал шығармасы – «Жыл мезгілдері» деп аталатын скрипкаға арналған төрт концерт. Олар: «Көктем», «Жаз», «Күз», «Қыс».": "Вивальдиниң әң тонулған әсири — «Жил пәсиллири» дәп атилидиған скрипкиға беғишланған төт концерт. Улар: «Баһар», «Яз», «Күз», «Қиш».",
"«Шат көңіл» әні": "«Шат көңіл» нахшиси",
"Бұл әннің өлеңін Б. Тәжібаев жазған, әнін С. Еркімбеков шығарған. Ән вальс ырғағымен орындалады, көңілді, жарқын.": "Бу нахшиниң шеирини Б. Тәжібаев йезип чиққан, нахшисини С. Еркімбеков чиққан. Нахша вальс ритми билән орунлиниду, шат, йоруқ.",
"Оркестр және дирижёр": "Оркестр вә дирижёр",
"Оркестр – музыкалық шығармаларды орындайтын аспаптар ұжымы. Дирижёр – музыканттар ұжымын басқарады және шығарманың әдемі орындалуына жауап береді.": "Оркестр — музикилиқ әсәрләрни орунлайдиған әсвапларниң топи. Дирижёр — музыкантлар топини башқуриду вә әсәрниң чирайлиқ орунлинишиға мәсул болиду.",
