"21-сабақ. Музыкадағы жыл мезгілдері (жалғасы)": "21-дәрис. Музикидики жил пәсиллири (давами)",
"Музыкадағы жыл мезгілдері (жалғасы)": "Музикидики жил пәсиллири (давами)",
"Жыл мезгілдері туралы шығармаларды таныру, канон, оркестр, дирижёр, симфониялық поэма және сюита ұғымдарын түсіндіру.": "Жил пәсиллири һәққидики әсәрләрни тонуш, канон, оркестр, дирижёр, симфонийилик поэма вә сюита чүшәнчилирини чүшәндүрүш.",
"Жыл – он екі ай": "Жил — он икки ай",
"Жыл мезгілдеріне арналған ән мен музыкалық шығарма көп. Домбырашы, композитор Төлепберген Тоқжанов домбыраға арнап «Жыл – он екі ай» пьесаларын жазған, онда он екі айдың ерекшелігі суреттелген.": "Жил пәсиллиригә беғишланған нахша вә музикилиқ әсәр көп. Домбичи, композитор Төлепберген Тоқжанов домбираға беғишлап «Жил — он икки ай» пьесилирини йезип чиққан, уларда он икки айниң алаһидилики тәсвирләнгән.",
"«Жұмбақ әуендер» ойыны": "«Тапмақ мәлодийәләр» оюни",
"Тыңдалған музыкаға қарай шығарма атын түсі сәйкес келетін қағазбен көрсетесің: «Ақпан – Бұрқасын» – ақ, «Қыркүйек – Күзгі той» – сары, «Сәуір – Көктемгі тамшылар» – жасыл, «Шілде – Жаз биі» – қызыл. Түстерді дұрыс көрсеткен топ жеңімпаз болады.": "Аңланған музикиға асаслинип, әсәрниң намини өңи мас келидиған қәғәз билән көрситисән: «Феврал — Боран» — ақ, «Сентәбир — Күзлүк той» — сериқ, «Апрел — Баһар тамчилири» — яшил, «Июль — Яз уссули» — қизил. Рәңләрни тоғра көрсәткән гуруппа ғалип болиду.",
"Канон": "Канон",
"Әнді орындаудың бір тәсілі – канон. Әнді топтарға бөліп, шумақты кезектесіп, бірінен кейін бірі бастап айтады. «Жау-жау, жаңбыр!» әнінің сөзін Ш. Сариев, әнін К. Дүйсекеев жазған.": "Нахшини орунлашниң бир усули — канон. Нахшини гуруппиларға бөлүп, куплетни кезәклишип, бир-биридин кейин башлап ейтиду. «Жау-жау, жаңбыр!» нахшисиниң сөзини Ш. Сариев, нахшисини К. Дүйсекеев йезип чиққан.",
"Оркестр – түрлі музыкалық аспаптарда шығармалар орындайтын ұжым. Дирижёр – музыкант-орындаушылар ұжымын басқаратын маман.": "Оркестр — һәр хил музикилиқ қураллардә әсәрләрни орунлайдиған коллектив. Дирижёр — музыкант-орунлиғучилар коллективини башқуридиған мутәхәссис.",
"Симфониялық поэма және сюита": "Симфонийилик поэма вә сюита",
"Симфониялық поэма – бір бөлімді, симфониялық оркестрге арналған бағдарламалық шығарма. Сюита – бір идеяға бағындырылған, әртүрлі пьесадан құрастырылған музыкалық шығарма.": "Симфонийилик поэма — бир қисимлиқ, симфонийилик оркестрға беғишланған программилиқ әсәр. Сюита — бир ғайигә бойсундурулған, һәр хил пьесилардин тузулгән музикилиқ әсәр.",
