"Арал тағдыры — ел тағдыры": "Арал тәғдири — әл тәғдири",
"Арал мәселесі туралы музыка мен суреттің көмегімен айта білу және Қ. Сайжанның күйін, Т. Шевченконың пейзаждарын, «Аралым» әнін ажырату.": "Арал мәсилиси һәққидә музика вә рәсимниң ярдими билән сөзләп берәлләш һәм Қ. Сайжанниң күйини, Т. Шевченкониң пейзажлирини, «Аралым» нахшисини пәриқләндүрүш.",
"Арал мәселесі": "Арал мәсилиси",
"Арал теңізі тартылып барады. Желмен ұшқан ащы тұз табиғатқа да, адам денсаулығына да зиян келтіреді.": "Арал деңизи қуруп бармақта. Шамалда учқан аччиқ туз тәбиәткиму, адәмниң саламәтлигигиму зиян кәлтүриду.",
"Бүкіл әлемнің қайғысы": "Пүтүн дунияниң ғәми",
"Арал мәселесі тек Қазақстан үшін ғана емес, басқа мемлекеттер үшін де өзекті. Отандық және шетелдік ғалымдар Аралды қайта толтыру жолдарын қарастыруда.": "Арал мәсилиси пәқәт Қазақстан үчүнла әмәс, башқа дөләтләр үчүнму муһим. Ичкири вә чәт әллик алимлар Арални қайта толтуруш йолларини қарап чиқмақта.",
"«Арал тағдыры» күйі": "«Арал тәғдири» күйи",
"Бұл — Қ. Сайжанның күйі. Күйдің орындалуы адамның мұңды, қайғылы сезімдерін білдіреді, композитор тыңдаушыға маңызды ойды жеткізуге тырысқан.": "Бу — Қ. Сайжанниң күйи. Күйниң орунлиниши адәмниң муңлуқ, ғәмлик һессиятлирини ипадилләйду, композитор аңлиғучиға муһим пикирни йәткүзүшкә тиришқан.",
"Тарас Шевченко": "Тарас Шевченко",
"Тарас Григорьевич Шевченко (1814–1861) — украиннің әйгілі ақыны әрі суретшісі. 1838 жылы Санкт-Петербург қаласының Көркемсурет академиясын бітірген.": "Тарас Григорьевич Шевченко (1814–1861) — украинниң мәшһур шаири вә рәссами. 1838-жили Санкт-Петербург шәһиридики Сүрәт-сәнәт академийәсини пүттүргән.",
"Шевченко және Арал": "Шевченко вә Арал",
"1848 жылы ол А.И. Бутаковтың басшылығымен Арал теңізін зерттеу экспедициясына қатысып, 350-ден астам пейзаж, портрет салған. Маңғыстау облысындағы Түпқараған ауданының орталығы «Форт-Шевченко» деп аталады.": "1848-жили у А.И. Бутаковниң рәһбәрлики астида Арал деңизини тәтқиқ қилиш экспедицияси қатнишип, 350 дин артуқ пейзаж, портрет сизған. Маңғыстау областидики Түпқараған наһийәсиниң мәркизи «Форт-Шевченко» дәп атилиду.",
