"23-сабақ. Ядролық жарылысқа — «Жоқ» дейміз!": "23-дәрис. Ядролуқ партлашқа — «Яқ» дәймиз!",
"Ядролық жарылысқа — «Жоқ» дейміз!": "Ядролуқ партлашқа — «Яқ» дәймиз!",
"Полигон мен радиация ұғымдарын түсіндіру, «Заман-ай» мен «Ядролық жарылысқа — «Жоқ» дейміз!» әндерінің авторларын атау және әндердің мазмұнын сипаттау.": "Полигон вә радиация чүшәнчилирини чүшәндүрүш, «Заман-ай» вә «Ядролуқ партлашқа — «Яқ» дәймиз!» нахшилириниң муәллиплирини аташ вә нахшиларниң мәзмунини тәсвирләш.",
"Ядролық қарусыз аймақ": "Ядролуқ қуралсиз зона",
"Қазақстан өзін «ядролық қарусыз аймақ» деп жариялады. Біздің елдің мақсаты — бейбітшілік пен адамдардың денсаулығын сақтау.": "Қазақстан өзини «ядролуқ қуралсиз зона» дәп елан қилди. Биздики әлниң мәқсити — тинчлиқ вә адәмләрниң саламәтлигини сақлаш.",
"Декларация": "Декларация",
"1991 жылы 28 тамызда Декларация қабылданды. Семей полигоны жабылды, ел атом қаруынан бас тарту жолын жалғастырды.": "1991-жили 28-август Декларация қобул қилинди. Семәй полигони етилди, әл атом қуралидин ваз кечиш йолини давамлаштурди.",
"Полигон": "Полигон",
"Полигон — қару-жарақ пен әскери техникаға, көбінесе ядролық сынақ жүргізуге арналған арнайы бөлінген және жабдықталған аймақ.": "Полигон — қурал-ярағ вә һәрбий техникиға, көпинчә ядролуқ синақ өткүзүшкә беғишланған алаһидә ажритилған вә җабдуқланған зона.",
"Радиация": "Радиация",
"Радиация (өткір радиация) — ядролық жарылыс кезінде тарайтын радиоактивті сәулелер.": "Радиация (өткүр радиация) — ядролуқ партлаш вақтида тарқилидиған радиоактивлиқ нурлар.",
"Екі ән": "Икки нахша",
