"Ғазиза Жұбанова (1927–1993) — композитор. Ол Алматы қаласында музыканттар отбасында дүниеге келген. Әкесі — атақты композитор Ахмет Жұбанов.": "Ғазиза Жұбанова (1927–1993) — композитор. У Алмута шәһиридә музыканттар аилисидә туғулған. Атиси — мәшһур композитор Ахмет Жұбанов.",
"Композитордың шығармалары": "Композиторниң әсәрлири",
"Ғ. Жұбанова опера, балет, оратория, ән, хор жазған. Оның «Хиросима» балеті Қазақстан музыка өнерінде үлкен жаңалық болды.": "Ғ. Жұбанова опера, балет, оратория, нахша, хор йезиған. Униң «Хиросима» балети Қазақстан музика сәнитидә чоң йеңилиқ болди.",
"Мемлекеттік сыйлық": "Дөләт мукапати",
"«Хиросима» балеті үшін Ғ. Жұбановаға 1970 жылы Қазақстанның Мемлекеттік сыйлығы берілді.": "«Хиросима» балети үчүн Ғ. Жұбановаға 1970-жили Қазақстанниң Дөләт мукапати берилди.",
"Балет": "Балет",
"Балет — музыкалық-хореографиялық қойылым. Оның мазмұны, кейіпкерлердің ой-сезімі музыка мен би арқылы көрсетіледі.": "Балет — музикилиқ-хореографиялик қойулум. Униң мәзмуни, қәһриманларниң ой-һессияти музика вә уссул арқилиқ көрситилиду.",
"Реквием": "Реквием",
"Реквием — көпдауысты, қайғылы музыкалық шығарма. «Хиросима» балетінің соңында реквием-гимн естіледі: музыка жер бетінде ешқашан ядролық жарылыстар болмасын деген тілекті жеткізеді.": "Реквием — көп авазлиқ, ғәмлик музикилиқ әсәр. «Хиросима» балетиниң ахирида реквием-гимн аңлиниду: музика жәр йүзидә һеч қачан ядролуқ партлашлар болмисун дегән арзуни йәткүзиду.",
"Кім? Не?": "Ким? Немә?",
"Әр карточканы дұрыс топқа орналастыр: композитор, сөзін жазған не аударған адам немесе шығарма атауы.": "Һәр карточкини тоғра гуруппиға орунлаштур: композитор, сөзини йезиған яки тәрҗимә қилған адәм яки әсәр нами.",
"Сөзін жазған не аударған": "Сөзини йезиған яки тәрҗимә қилған",
