"Балеттің оқиғасы жеке бір отбасының ғана тағдыры емес, бүкіл халықтың қайғысы ретінде баяндалған.": "Балетниң вақиәси айрим бир аилиниң тәғдири әмәс, пүтүн хәлқниң ғәми сүпитидә баян қилинған.",
"Сакура көктемде қызғылт түсті нәзік гүл ашады.": "Сакура баһарда қизғучу рәңлик нәпис гүл ачиду.",
"Бұл тілек музыка мен балет арқылы жеткізіледі.": "Бу арзу музика вә балет арқилиқ йәткүзүлиду.",
"Балетте жапон халқының қарапайым отбасының тіршілігі бейнеленген.": "Балетта японлар хәлқиниң аддий аилисиниң турмуши көрситилгән.",
"Дұрыс. Ол опера, балет, оратория, ән жазған композитор.": "Тоғра. У опера, балет, оратория, нахша йезиған композитор.",
"Бұрыс. Ол опера, балет, оратория, хор да жазған.": "Хата. У опера, балет, оратория, хорму йезиған.",
"Дұрыс. Сыйлық 1970 жылы берілді.": "Тоғра. Мукапат 1970-жили берилди.",
"Дұрыс. Балет — музыкалық-хореографиялық қойылым.": "Тоғра. Балет — музикилиқ-хореографиялик қойулум.",
"Бұрыс. Реквием — қайғылы музыкалық шығарма.": "Хата. Реквием — ғәмлик музикилиқ әсәр.",
"Дұрыс. Балеттің оқиғасы жеке бір отбасының ғана тағдыры емес, бүкіл халықтың қайғысы ретінде баяндалған.": "Тоғра. Балетниң вақиәси айрим бир аилиниң тәғдири әмәс, пүтүн хәлқниң ғәми сүпитидә баян қилинған.",
"Бұрыс. «Сакура» — жапонның халық әні.": "Хата. «Сакура» — японларниң хәлқ нахшиси.",
"Дұрыс. Сакура көктемде қызғылт түсті нәзік гүл ашады.": "Тоғра. Сакура баһарда қизғучу рәңлик нәпис гүл ачиду.",
"Дұрыс. Бұл тілек музыка мен балет арқылы жеткізіледі.": "Тоғра. Бу арзу музика вә балет арқилиқ йәткүзүлиду.",
"Дұрыс. Балетте жапон халқының қарапайым отбасының тіршілігі бейнеленген.": "Тоғра. Балетта японлар хәлқиниң аддий аилисиниң турмуши көрситилгән.",
"Табыңыз: Сөзін жазған не аударған": "Тап: Сөзини йезиған яки тәрҗимә қилған",
"Табыңыз: Шығарма": "Тап: Әсәр",
"Табыңыз: Балет": "Тап: Балет",
"Табыңыз: Реквием": "Тап: Реквием",
"Табыңыз: «Сакура» әні": "Тап: «Сакура» нахшиси",
"25-сабақ. Ел қорғауға дайынбыз!": "25-дәрис. Ватанни қоғдашқа тәйярмиз!",
"Ел қорғауға дайынбыз!": "Ватанни қоғдашқа тәйярмиз!",
"Атап айту: «Сарбаздар жыры» мен «Мәңгілік алау» балетінің авторларын, тақырыбын және ел қорғау туралы музыканың мәнін түсіндіру.": "Аташ: «Сәрбазлар нахшиси» билән «Мәңгү алов» балетиниң авторлирини, темисини вә Ватанни қоғдаш һәққидики музикиниң мәнасини чүшәндүрүш.",
"Ата-бабалар аманаты": "Ата-бовилар аманити",
"Кім болсақ та, қайда жүрсек те, өз туған жерімізді, табиғатымызды аялап, қорғауымыз керек. Бұл — ата-бабаларымыздың бізге қалдырған аманаты.": "Биз кимму болсақ, қәйәрдә жүрсәкму, өз туғулған йеримизни, тәбиитимизни әзиз көрүп, қоғдишимиз керәк. Бу — ата-бовилиримизниң бизгә қалдурған аманити.",
"Табиғатты қорғау": "Тәбиәтни қоғдаш",
"Арал теңізі мен Семей полигоны мәселелерін өткен сабақтарда білдік. Жеріміздің табиғатына зиян келіп жатыр, сондықтан елімізді, қоршаған ортаны қорғауға дайын болуымыз керек.": "Арал деңизи билән Семей полигони мәсилилирини өткән дәрисләрдә билдуқ. Йеримизниң тәбиитигә зиян кәлмәктә, шуңа Ватинимизни, әтрапимиздики муһитни қоғдашқа тәйяр болушимиз керәк.",
"«Сарбаздар жыры»": "«Сәрбазлар нахшиси»",
"Бұл — қазақ сарбаздары туралы ән. Өлеңін А. Асылбек жазған, әнін Н. Айтбаева шығарған. Әнде қайырма бар.": "Бу — қазақ сәрбазлири һәққидики нахша. Шеирини А. Асылбек язған, нахшисини Н. Айтбаева ижад қилған. Нахшида қайтурма бар.",
"Әннің тақырыбы": "Нахшиниң темиси",
"«Сарбаздар жыры» елін қорғайтын батыл сарбаздарды дәріптейді. Ән тыныштық пен бейбіт өмір арманын жеткізеді.": "«Сәрбазлар нахшиси» Ватанни қоғдайдиған баһадир сәрбазларни мәдһийиләйду. Нахша аманлиқ вә тинч һаят арзусини йәткүзиду.",
"«Мәңгілік алау» балеті": "«Мәңгү алов» балети",
"Бұл — бір актілі балеттен үзінді, музыкасын С. Еркімбеков жазған. Балет 12 нөмірден тұрады және соғыс пен бейбітшілік туралы айтады. Ондағы нөмірлердің бірі — «Реквием».": "Бу — бир пәрдилик балеттин үзүндә, музикисини С. Еркимбеков язған. Балет 12 номурдин тәркиб тапиду вә уруш билән тинчлиқ һәққидә сөзләйду. Униңдики номурларниң бири — «Реквием».",
