"Бұрыс. Елімізді, қоршаған ортаны қорғауға әрқайсымыз дайын болуымыз керек.": "Хата. Ватинимизни, әтрапимиздики муһитни қоғдашқа һәр биримиз тәйяр болушимиз керәк.",
