"Табыңыз: Балеттегі нөмірдің атауы": "Тап: Балеттики номурниң аталғуси",
"Табыңыз: Адамның аты-жөні немесе шығарма атауы": "Тап: Адәмниң исим-фамилиси яки әсәрниң аталғуси",
"26-сабақ. Қоршаған ортамызды сақтайық!": "26-дәрис. Әтрапимиздики муһитни сақлайли!",
"Қоршаған ортамызды сақтайық!": "Әтрапимиздики муһитни сақлайли!",
"Қоршаған ортаны қорғайтын мамандықтарды атау, «Атамекен» әні мен «Мәңгілік алау» балетін таныту және кейіпкер, көрініс ұғымдарын түсіндіру.": "Әтрапимиздики муһитни қоғдайдиған кәсипләрни аташ, «Атамекен» нахшиси билән «Мәңгү алов» балетини тонуштуруш вә қәһриман, көрүнүш чүшәнчилирини чүшәндүрүш.",
"«Атамекен» әні": "«Атамекен» нахшиси",
"Бұл әннің сөзін Ш. Сариев, әнін Ж. Тұяқбаев жазған. Ән Отанымыздың әдемі табиғатын мадақтайды.": "Бу нахшиниң сөзини Ш. Сариев, нахшисини Ж. Туяқбаев язған. Нахша Ватинимизниң гөзәл тәбиитини мәдһийиләйду.",
"Төрт топ, төрт мамандық": "Төт топ, төт кәсип",
"Сабақта оқушылар төрт топқа бөлінеді: Экологтер, Өртсөндірушілер, Балықшылар және Орманшылар. Әр топ өз мамандығы туралы таныстырылым дайындайды.": "Дәристә оқуғучилар төт топқа бөлүниду: Экологлар, Янғинни өчүргүчиләр, Балиқчилар вә Орманчилар. Һәр топ өз кәсипи һәққидә тонуштуруш тәйярлайду.",
"Экологтер мен өртсөндірушілер": "Экологлар билән янғинни өчүргүчиләр",
"Эколог қоршаған ортамен үйлесімді өмір сүруге көмектеседі. Өртсөндірушілер күні-түні қауіп пен қатерден сақтап, өрт шықса көмекке келеді.": "Эколог әтрапимиздики муһит билән маслишип яшашқа ярдәмләшиду. Янғинни өчүргүчиләр күндүз-кечә хәвип-хәтәрдин сақлайду, янғин чиқса ярдәмгә келиду.",
"Балықшылар мен орманшылар": "Балиқчилар билән орманчилар",
"Балықшылар балықтың қасиетін біледі және балық өсетін су ортасының тазалығын сақтайды. Орманшылар орманды қорғап, түрлі міндеттерді атқарады.": "Балиқчилар балиқниң хусусийитини билиду вә балиқ өсидиған су муһитиниң тазилиқини сақлайду. Орманчилар ормандын қоғдап, түрлүк вәзипиләрни ада қилиду.",
"Бұл балеттің музыкасын С. Еркімбеков жазған. Балет — музыкалық-хореографиялық қойылым. Онда кейіпкерлер сөйлемей, би мен музыка арқылы өз ойын көрсетеді.": "Бу балетниң музикисини С. Еркимбеков язған. Балет — музикилиқ-хореографиялик сәһнә әсири. Униңда қәһриманлар сөзлимәй, уссул вә музика арқилиқ өз ойини көрситиду.",
